package com.example.complaintmanagement.service.impl; import com.example.complaintmanagement.dto.*; import com.example.complaintmanagement.entity.*; import com.example.complaintmanagement.repository.UserRepository; import com.example.complaintmanagement.security.JwtService; import com.example.complaintmanagement.service.*; import com.example.complaintmanagement.exception.BadRequestException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service public class AuthServiceImpl implements AuthService {private final UserRepository repo;private final PasswordEncoder enc;private final JwtService jwt;private final CurrentUserService current;private final com.example.complaintmanagement.mapper.UserMapper mapper=new com.example.complaintmanagement.mapper.UserMapper(); public AuthServiceImpl(UserRepository r,PasswordEncoder e,JwtService j,CurrentUserService c){repo=r;enc=e;jwt=j;current=c;} public AuthDtos.AuthResponse register(AuthDtos.RegisterRequest r){if(repo.existsByUsername(r.username()))throw new BadRequestException("Username already exists");if(repo.existsByEmail(r.email()))throw new BadRequestException("Email already registered");User u=User.builder().firstName(r.firstName()).lastName(r.lastName()).username(r.username()).email(r.email()).password(enc.encode(r.password())).role(Role.USER).active(true).createdAt(LocalDateTime.now()).build();repo.save(u);return new AuthDtos.AuthResponse(jwt.generate(u.getId(),u.getUsername(),u.getRole().name()),mapper.toResponse(u));} public AuthDtos.AuthResponse login(AuthDtos.LoginRequest r){User u=repo.findByUsername(r.username()).orElseThrow(()->new BadRequestException("Invalid username or password"));if(!u.isActive()||!enc.matches(r.password(),u.getPassword()))throw new BadRequestException("Invalid username or password");return new AuthDtos.AuthResponse(jwt.generate(u.getId(),u.getUsername(),u.getRole().name()),mapper.toResponse(u));} public UserDtos.UserResponse me(){return mapper.toResponse(current.get());}}
